        }
        control.checkpoint().map_err(stopped)?;
        crate::validate::shape_attributes(self, token.mark.scene, &value, control)?;
        self.scenes[i].shapes[id.index()] = value;
        Ok(())
    }
    pub fn finalize_shape_colors(
        &mut self,
        token: &DraftToken,
        id: ShapeId,
        colors: &[[u8; 4]],
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let i = self.draft_index(token)?;
        self.draft_slot(token, 3, id.index(), self.scenes[i].shapes.len())?;
        let shape = self
            .scene(token.mark.scene)?
            .shape(id)
            .ok_or_else(|| invalid(0))?;
        let range = shape.edges;
        if range.count != colors.len() || range.first < token.mark.lengths[1] {
            return Err(invalid(0));
        }
        range.require(self.scenes[i].edge_colors.len(), 0)?;
        control.checkpoint().map_err(stopped)?;
        for _ in colors {
            control.charge(WorkKind::PaintVisit, 1).map_err(stopped)?;
        }
        self.scenes[i].edge_colors[range.first..range.end().ok_or_else(|| invalid(0))?]
            .copy_from_slice(colors);
        Ok(())
    }
    pub fn finalize_transform(
        &mut self,
        token: &DraftToken,
        id: TransformId,
        value: TransformFrame,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let i = self.draft_index(token)?;
        self.draft_slot(token, 7, id.index(), self.scenes[i].transforms.len())?;
        let old = self
            .scene(token.mark.scene)?
            .transform(id)
            .ok_or_else(|| invalid(0))?;
        if old.parent != value.parent || old.source_offset != value.source_offset {
            return Err(invalid(0));
        }
        control.checkpoint().map_err(stopped)?;
        crate::validate::transform(self, token.mark.scene, &value, control)?;
        self.scenes[i].transforms[id.index()] = value;
        Ok(())
    }
    pub fn finalize_clip(
        &mut self,
        token: &DraftToken,
        id: ClipId,
        value: Clip,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let i = self.draft_index(token)?;
        self.draft_slot(token, 18, id.index(), self.scenes[i].clips.len())?;
        let old = self
            .scene(token.mark.scene)?
            .clip(id)
            .ok_or_else(|| invalid(0))?;
        if old.parent != value.parent {
            return Err(invalid(0));
        }
        let old_bytes = add(bytes(&old.geometry.edges)?, bytes(&old.geometry.shapes)?)?;
        control.checkpoint().map_err(stopped)?;
        crate::validate::clip(self, token.mark.scene, &value, control)?;
        let new = add(
            bytes(&value.geometry.edges)?,
            bytes(&value.geometry.shapes)?,
        )?;
        self.pending(new)?;
        self.retain(new)?;
        self.scenes[i].clips[id.index()] = value;
        self.stats.live_bytes -= old_bytes;
        Ok(())
    }
    pub fn finalize_mask(
        &mut self,
        token: &DraftToken,
        id: MaskId,
        value: Mask,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let i = self.draft_index(token)?;
        self.draft_slot(token, 12, id.index(), self.scenes[i].masks.len())?;
        self.scene(token.mark.scene)?
            .mask(id)
            .ok_or_else(|| invalid(0))?;
        control.checkpoint().map_err(stopped)?;
        crate::validate::mask(self, token.mark.scene, &value, control)?;
        self.scenes[i].masks[id.index()] = value;
        Ok(())
    }
    pub fn finalize_group(
        &mut self,
        token: &DraftToken,
        id: GroupId,
        value: OpacityGroup,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let i = self.draft_index(token)?;
        self.draft_slot(token, 9, id.index(), self.scenes[i].groups.len())?;
        let old = self
            .scene(token.mark.scene)?
            .group(id)
            .ok_or_else(|| invalid(0))?;
        if old.parent != value.parent || old.shapes.first != value.shapes.first {
            return Err(invalid(0));
        }
        control.checkpoint().map_err(stopped)?;
        crate::validate::group(self, token.mark.scene, &value, id.index(), control)?;
        self.scenes[i].groups[id.index()] = value;
        Ok(())
    }
    pub fn finalize_fill_paint(
        &mut self,
        token: &DraftToken,
        index: usize,
        value: Paint,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.finalize_paint(token, index, value, true, control)
    }
    pub fn finalize_stroke_paint(
        &mut self,
        token: &DraftToken,
        index: usize,
        value: Paint,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.finalize_paint(token, index, value, false, control)
    }
    fn finalize_paint(
        &mut self,
        token: &DraftToken,
        index: usize,
        value: Paint,
        fill: bool,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let i = self.draft_index(token)?;
        let (table, len) = if fill {
            (14, self.scenes[i].fill_paints.len())
        } else {
            (15, self.scenes[i].stroke_paints.len())
        };
        self.draft_slot(token, table, index, len)?;
        control.checkpoint().map_err(stopped)?;
        crate::validate::paint(self, token.mark.scene, &value, control)?;
        if fill {
            self.scenes[i].fill_paints[index] = value;
        } else {
            self.scenes[i].stroke_paints[index] = value;
        }
        Ok(())
    }
    pub fn finalize_filter(
        &mut self,
        token: &DraftToken,
        id: FilterId,
        mut value: Filter,
        primitives: &[FilterPrimitive],
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let i = self.draft_index(token)?;
        self.draft_slot(token, 10, id.index(), self.scenes[i].filters.len())?;
        self.scene(token.mark.scene)?
            .filter(id)
            .ok_or_else(|| invalid(0))?;
        control.checkpoint().map_err(stopped)?;
        crate::validate::filter(value, primitives, control)?;
        for p in primitives {
            control.charge(WorkKind::FilterPixel, 1).map_err(stopped)?;
            if p.source_offset > self.source.len() {
                return Err(invalid(p.source_offset));
            }
        }
        if add(self.scenes[i].filter_primitives.len(), primitives.len())? > 65536 {
            return Err(limit(LimitKind::Filters));
        }
        room!(self, i, filter_primitives, primitives.len(), 65536, 0);
        control.checkpoint().map_err(stopped)?;
        value.primitives = TableRange {
            first: self.scenes[i].filter_primitives.len(),
            count: primitives.len(),
        };
        self.scenes[i]
            .filter_primitives
            .extend_from_slice(primitives);
        self.scenes[i].filters[id.index()] = value;
        Ok(())
    }
}

//! Complete computed plan handoff. Mapping is carried at suspension, never
//! reconstructed by parsing source on resume. Original descriptors stay intact.
use crate::{
    types::{invalid, stopped},
    *,
};
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct PatternMapping {
    pub tile_origin: [f64; 2],
    pub user_to_base: Affine,
    pub pattern_transform: Affine,
    pub user_inverse: Affine,
    pub viewport: [f64; 2],
    pub bounds: [f64; 4],
    pub source_map: SourceMap,
    pub opacity: f64,
}
impl PatternMapping {
    pub fn pixel_inverse(self, descriptor: PatternDescriptor) -> Result<Affine> {
        use vexel_geometry::{affine_compose, affine_valid};
        if !self.tile_origin.into_iter().all(f64::is_finite)
            || !self.viewport.into_iter().all(|v| v.is_finite() && v > 0.)
            || !self.bounds.into_iter().all(f64::is_finite)
            || self.bounds[2] < 0.
            || self.bounds[3] < 0.
            || !self.opacity.is_finite()
            || !(0.0..=1.0).contains(&self.opacity)
            || !affine_valid(self.user_inverse)
            || !affine_valid(self.source_map.transform)
        {
            return Err(invalid(descriptor.error_offset));
        }
        // The supplied computed inverse must implement inverse(patternTransform)
        // followed by translation(-tileOrigin), as in the original algorithm.
        let back = affine_compose(self.user_to_base, self.pattern_transform)
            .ok_or_else(|| invalid(descriptor.error_offset))?;
        let expected = [1., 0., 0., 1., -self.tile_origin[0], -self.tile_origin[1]];
        for (a, b) in [back.a, back.b, back.c, back.d, back.e, back.f]
            .into_iter()
            .zip(expected)
        {
            if (a - b).abs() > 1e-9 * a.abs().max(b.abs()).max(1.) {
                return Err(invalid(descriptor.error_offset));
            }
        }
        let scale = Affine {
            a: descriptor.width as f64 / descriptor.tile_width,
            d: descriptor.height as f64 / descriptor.tile_height,
            b: 0.,
            c: 0.,
            e: 0.,
            f: 0.,
        };
        affine_compose(scale, self.user_to_base).ok_or_else(|| invalid(descriptor.error_offset))
    }
}
#[derive(Debug, Clone, Copy)]
pub(crate) struct PatternContinuation {
    mapping: PatternMapping,
    parent: SceneId,
    shape: ShapeId,
    channel: PaintChannel,
    draft: u64,
    generation: u64,
    request: Option<RequestToken>,
    job: LedgerIdentity,
}
impl PatternTickets {
    pub fn request_mapped<'a>(
        &mut self,
        builder: &'a SceneBuilder,
        draft: &DraftToken,
        source: &DecodeSource<'_>,
        child: SceneId,
        descriptor: PatternDescriptor,
        mapping: PatternMapping,
        shape: ShapeId,
        channel: PaintChannel,
        job: &RasterJob,
        control: &mut dyn WorkControl,
    ) -> Result<PatternRequest<'a>> {
        let i = builder.draft_index(draft)?;
        builder.draft_slot(draft, 3, shape.index(), builder.scenes[i].shapes.len())?;
        job.validate_source(builder.source_owner())?;
        if !std::sync::Arc::ptr_eq(builder.source_owner(), source.source_owner()) {
            return Err(invalid(0));
        }
        let definition = source.element(
            descriptor.definition,
            crate::memory::add(descriptor.definition.0, 1)?,
            control,
        )?;
        if definition.tokens()[descriptor.definition.0]
            .local_name
            .slice(source.source())
            != Some(b"pattern")
        {
            return Err(invalid(descriptor.error_offset));
        }
        let value = builder
            .scene(draft.mark.scene)?
            .shape(shape)
            .copied()
            .ok_or_else(|| invalid(0))?;
        if value.source != mapping.source_map
            || mapping
                .source_map
                .element
                .slice(builder.source_owner())
                .is_none()
        {
            return Err(invalid(0));
        }
        mapping.pixel_inverse(descriptor)?;
        let child_view = builder.scene(child)?;
        if child == draft.mark.scene || child.index() < draft.scene_count {
            return Err(invalid(0));
        }
        let request = self.request(child_view, descriptor, control)?;
        self.pending.as_mut().ok_or_else(|| invalid(0))?.production = Some(PatternContinuation {
            mapping,
            parent: draft.mark.scene,
            shape,
            channel,
            draft: draft.nonce,
            generation: builder.generation,
            request: builder.request_identity(),
            job: job.owner_identity(),
        });
        Ok(request)
    }
    /// Transfer admitted job output directly into the builder's owned pattern;
    /// then publish and attach the exact fill/stroke mapping. No raw Vec or Tile
    /// escapes this operation. Late errors unwind just this publication suffix.
    pub fn complete_mapped(
        &mut self,
        ticket: PatternTicket,
        builder: &mut SceneBuilder,
        draft: &DraftToken,
        job: &mut RasterJob,
        result: Result<JobRenderOutput>,
        control: &mut dyn WorkControl,
    ) -> Result<(PatternId, usize)> {
        let pending = self.pending.as_ref().ok_or_else(|| invalid(0))?;
        if pending.ticket != ticket {
            return Err(invalid(0));
        }
        let p = pending.production.ok_or_else(|| invalid(0))?;
        let descriptor = pending.descriptor;
        job.validate_source(builder.source_owner())?;
        if builder.owner != p.parent.owner || job.owner_identity() != p.job {
            return Err(invalid(0));
        }
        let child = pending.scene;
        let live = builder.draft_index(draft).is_ok()
            && draft.nonce == p.draft
            && draft.mark.scene == p.parent
            && builder.generation == p.generation
            && builder.request_identity() == p.request
            && builder
                .scene(child)
                .is_ok_and(|view| view.scene(child).is_some())
            && builder
                .scene(p.parent)
                .is_ok_and(|view| view.shape(p.shape).is_some());
        if !live {
            self.pending = None;
            if let Ok(output) = result {
                if output.validate(job).is_ok() {
                    job.release(output.pixels)?;
                }
            }
            return Err(invalid(0));
        }
        let output = match result {
            Ok(output) => output,
            Err(error) => {
                self.pending = None;
                return Err(error);
            }
        };
        output.validate(job)?;
        if output.width != descriptor.width
            || output.height != descriptor.height
            || output.generation != p.generation
        {
            return Err(invalid(0));
        }
        let inverse = p.mapping.pixel_inverse(descriptor)?;
        let mut shape = *builder
            .scene(p.parent)?
            .shape(p.shape)
            .ok_or_else(|| invalid(0))?;
        let i = builder.draft_index(draft)?;
        builder.draft_slot(draft, 3, p.shape.index(), builder.scenes[i].shapes.len())?;
        let mut mark = builder.checkpoint_internal(p.parent)?;
        let result = (|| {
            control.checkpoint().map_err(stopped)?;
            let id = job.publish_pattern_output(output, builder, p.parent, descriptor, control)?;
            let paint = Paint {
                kind: PaintKind::Pattern,
                spread: Spread::Repeat,
                object_bounding_box: false,
                coordinates: [
                    p.mapping.tile_origin[0],
                    p.mapping.tile_origin[1],
                    descriptor.tile_width,
                    descriptor.tile_height,
                    0.,
                    0.,
                ],
                bounds: p.mapping.bounds,
                user_inverse: p.mapping.user_inverse,
                gradient_inverse: vexel_geometry::affine_identity(),
                stops: TableRange::EMPTY,
                pattern: Some(id),
                pattern_inverse: inverse,
                pattern_opacity: p.mapping.opacity,
            };
            let index = match p.channel {
                PaintChannel::Fill => builder.append_fill_paint(p.parent, paint, control)?,
                PaintChannel::Stroke => builder.append_stroke_paint(p.parent, paint, control)?,
            };
            match p.channel {
                PaintChannel::Fill => shape.fill_paint = Some(index),
                PaintChannel::Stroke => shape.stroke_paint = Some(index),
            }
            builder.finalize_shape(draft, p.shape, shape, control)?;
            Ok((id, index))
        })();
        if result.is_err() {
            mark.epoch = builder.scenes[i].epoch;
            builder.rollback_internal(mark)?;
            // Output may not yet have transferred. Clean it unconditionally.
            if job.slice(output.pixels).is_ok() {
                job.release(output.pixels)?;
            }
        }
        self.pending = None;
        result
    }
}
//! Explicit owning clients of the accepted ledger allocator. No Vec/lease escape.
//! Drop without release conservatively retains the charge until ledger teardown.
//! Clients must release before discarding; replacements count as a second active
//! record, so a query ledger configured for 65536 enforces overlap at that limit.
use crate::{
    types::{invalid, stopped},
    *,
};
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LedgerIdentity(u64);
#[derive(Debug)]
pub struct LedgerBuffer<T: Copy> {
    values: Option<Vec<T>>,
    lease: AllocationLease,
}
impl ChargeLedger {
    pub fn owner_identity(&self) -> LedgerIdentity {
        LedgerIdentity(self.identity())
    }
    pub fn require_owner(&self, identity: LedgerIdentity, source: &SourceOwner) -> Result<()> {
        if identity != self.owner_identity() || !std::sync::Arc::ptr_eq(source, self.source_owner())
        {
            return Err(invalid(0));
        }
        Ok(())
    }
    /// Requested reservation precedes physical reserve; actual capacity is
    /// admitted before return. Successful physical history survives cancellation.
    pub fn allocate_buffer<T: Copy>(
        &mut self,
        tag: AllocationTag,
        capacity: usize,
        control: &mut dyn WorkControl,
    ) -> Result<LedgerBuffer<T>> {
        let (values, lease) = self.allocate(tag, capacity, control)?;
        Ok(LedgerBuffer {
            values: Some(values),
            lease,
        })
    }
    pub(crate) fn require_lease(&self, lease: AllocationLease) -> Result<()> {
        // Defined alongside private registry access in accounting.rs.
        self.check_lease(lease)
    }
}
impl<T: Copy> LedgerBuffer<T> {
    fn require(&self, ledger: &ChargeLedger) -> Result<()> {
        if self.values.is_none() {
            return Err(invalid(0));
        }
        ledger.require_lease(self.lease)
    }
    pub fn values<'a>(&'a self, ledger: &ChargeLedger) -> Result<&'a [T]> {
        self.require(ledger)?;
        Ok(self.values.as_ref().ok_or_else(|| invalid(0))?)
    }
    pub fn values_mut<'a>(&'a mut self, ledger: &ChargeLedger) -> Result<&'a mut [T]> {
        self.require(ledger)?;
        Ok(self.values.as_mut().ok_or_else(|| invalid(0))?)
    }
    pub fn capacity(&self, ledger: &ChargeLedger) -> Result<usize> {
        self.require(ledger)?;
        Ok(self.values.as_ref().ok_or_else(|| invalid(0))?.capacity())
    }
    /// No allocation. Poll every real iteration; unpublished suffix is removed
    /// on cancellation, preserving the old values and admitted capacity.
    pub fn append(
        &mut self,
        ledger: &ChargeLedger,
        suffix: &[T],
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.require(ledger)?;
        control.checkpoint().map_err(stopped)?;
        let values = self.values.as_mut().ok_or_else(|| invalid(0))?;
        let len = values.len();
        let end = len
            .checked_add(suffix.len())
            .ok_or_else(crate::memory::arithmetic)?;
        if end > values.capacity() {
            return Err(invalid(0));
        }
        let result = (|| {
            for value in suffix {
                control.charge(WorkKind::SourceRead, 1).map_err(stopped)?;
                values.push(*value);
            }
            control.checkpoint().map_err(stopped)
        })();
        if result.is_err() {
            values.truncate(len);
        }
        result
    }
    /// Reserve old+new overlap, then controlled copy, then drop old storage before
    /// releasing its charge. Errors leave old data/token/capacity unchanged.
    pub fn replace_capacity(
        &mut self,
        ledger: &mut ChargeLedger,
        tag: AllocationTag,
        capacity: usize,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        self.require(ledger)?;
        if capacity < self.values(ledger)?.len() {
            return Err(invalid(0));
        }
        let mut replacement = ledger.allocate_buffer(tag, capacity, control)?;
        if let Err(error) = replacement.append(ledger, self.values(ledger)?, control) {
            replacement.release(ledger)?;
            return Err(error);
        }
        self.release(ledger)?;
        *self = replacement;
        Ok(())
    }
    pub fn truncate(&mut self, ledger: &ChargeLedger, len: usize) -> Result<()> {
        self.require(ledger)?;
        self.values
            .as_mut()
            .ok_or_else(|| invalid(0))?
            .truncate(len);
        Ok(())
    }
    /// Unconditional after cancellation, checked stale/double/foreign access.
    pub fn release(&mut self, ledger: &mut ChargeLedger) -> Result<()> {
        self.require(ledger)?;
        drop(self.values.take());
        ledger.release(self.lease)
    }
}
//! Additive production delegates. Legacy DecodeOperations remains an explicit
//! owned-fixture interface; no blanket conversion or default backend exists.
use crate::{
    types::{invalid, stopped},
    *,
};
use vexel_xml::XmlSpan;
#[derive(Debug, Clone, Copy)]
pub enum DefinitionTarget {
    Shape(ShapeId),
    Group(GroupId),
}
/// Same active scene/draft/source-token owner, not a naked slot or fake shape.
#[derive(Debug, Clone, Copy)]
pub struct DefinitionOwner {
    scene: SceneId,
    draft: u64,
    generation: u64,
    target: DefinitionTarget,
    element: ElementId,
}
impl DefinitionOwner {
    pub fn target(self) -> DefinitionTarget {
        self.target
    }
    pub fn element(self) -> ElementId {
        self.element
    }
    pub fn validate(self, ctx: &DefinitionContext<'_, '_>) -> Result<()> {
        ctx.validate()?;
        let active = ctx.builder.active_draft().ok_or_else(|| invalid(0))?;
        if ctx.scene != self.scene
            || active.scene != self.scene
            || active.nonce != self.draft
            || ctx.builder.generation != self.generation
        {
            return Err(invalid(0));
        }
        let view = ctx.builder.scene(self.scene)?;
        match self.target {
            DefinitionTarget::Shape(id) if view.shape(id).is_some() => Ok(()),
            DefinitionTarget::Group(id) if view.group(id).is_some() => Ok(()),
            _ => Err(invalid(0)),
        }
    }
}
impl SceneBuilder {
    pub fn definition_owner(
        &self,
        draft: &DraftToken,
        source: &DecodeSource<'_>,
        element: ElementId,
        target: DefinitionTarget,
        control: &mut dyn WorkControl,
    ) -> Result<DefinitionOwner> {
        self.draft_index(draft)?;
        if !std::sync::Arc::ptr_eq(self.source_owner(), source.source_owner()) {
            return Err(invalid(0));
        }
        source.element(element, crate::memory::add(element.0, 1)?, control)?;
        let view = self.scene(draft.mark.scene)?;
        match target {
            DefinitionTarget::Shape(id) if view.shape(id).is_some() => {}
            DefinitionTarget::Group(id) if view.group(id).is_some() => {}
            _ => return Err(invalid(0)),
        }
        Ok(DefinitionOwner {
            scene: draft.mark.scene,
            draft: draft.nonce,
            generation: self.generation,
            target,
            element,
        })
    }
    /// Atomic owning filter publication on a real (possibly empty) group. The
    /// child range is finalized later using the same guarded draft mutator.
    pub fn publish_group_filter(
        &mut self,
        draft: &DraftToken,
        owner: DefinitionOwner,
        filter: Filter,
        primitives: &[FilterPrimitive],
        control: &mut dyn WorkControl,
    ) -> Result<FilterId> {
        let i = self.draft_index(draft)?;
        if owner.scene != draft.mark.scene
            || owner.draft != draft.nonce
            || owner.generation != self.generation
        {
            return Err(invalid(0));
        }
        let DefinitionTarget::Group(group) = owner.target else {
            return Err(invalid(0));
        };
        self.draft_slot(draft, 9, group.index(), self.scenes[i].groups.len())?;
        let mut value = *self
            .scene(owner.scene)?
            .group(group)
            .ok_or_else(|| invalid(0))?;
        let mut mark = self.checkpoint_internal(owner.scene)?;
        let result = (|| {
            let id = self.append_filter(owner.scene, filter, primitives, control)?;
            value.filter = Some(id);
            self.finalize_group(draft, group, value, control)?;
            Ok(id)
        })();
        if result.is_err() {
            mark.epoch = self.scenes[i].epoch;
            self.rollback_internal(mark)?;
        }
        result
    }
}
/// Stops borrow the resolver cache, independently of temporary source/ledger
/// borrows. The resolver owns/meters its cache; this result owns no stop Vec.
#[derive(Debug)]
pub enum CachedPaint<'cache> {
    Plain(Paint),
    Gradient {
        template: &'cache GradientTemplateId,
        paint: Paint,
        stops: &'cache [PaintStop],
    },
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PaintChannel {
    Fill,
    Stroke,
}
impl SceneBuilder {
    pub fn append_cached_paint(
        &mut self,
        scene: SceneId,
        cached: CachedPaint<'_>,
        channel: PaintChannel,
        control: &mut dyn WorkControl,
    ) -> Result<usize> {
        match cached {
            CachedPaint::Gradient {
                template,
                paint,
                stops,
            } => match channel {
                PaintChannel::Fill => {
                    self.append_template_fill(scene, template, paint, stops, control)
                }
                PaintChannel::Stroke => {
                    self.append_template_stroke(scene, template, paint, stops, control)
                }
            },
            CachedPaint::Plain(paint) => {
                if matches!(paint.kind, PaintKind::Linear | PaintKind::Radial)
                    || paint.stops != TableRange::EMPTY
                {
                    return Err(invalid(0));
                }
                match channel {
                    PaintChannel::Fill => self.append_fill_paint(scene, paint, control),
                    PaintChannel::Stroke => self.append_stroke_paint(scene, paint, control),
                }
            }
        }
    }
}
pub trait CachedPaintResolver {
    fn resolve_cached<'cache>(
        &'cache mut self,
        source: &mut DecodeSource<'_>,
        ledger: &mut ChargeLedger,
        value: XmlSpan,
        edges: &[Edge],
        inverse: Affine,
        viewport: [f64; 2],
        control: &mut dyn WorkControl,
    ) -> Result<CachedPaint<'cache>>;
}
/// Actual shared resolve+publication operation; resolver output is used directly.
pub fn resolve_publish_cached(
    resolver: &mut dyn CachedPaintResolver,
    source: &mut DecodeSource<'_>,
    ledger: &mut ChargeLedger,
    builder: &mut SceneBuilder,
    scene: SceneId,
    value: XmlSpan,
    edges: &[Edge],
    inverse: Affine,
    viewport: [f64; 2],
    channel: PaintChannel,
    control: &mut dyn WorkControl,
) -> Result<usize> {
    ledger.require_owner(ledger.owner_identity(), source.source_owner())?;
    if !std::sync::Arc::ptr_eq(builder.source_owner(), source.source_owner()) {
        return Err(invalid(0));
    }
    builder.writable(scene)?;
    if value.slice(source.source()).is_none() {
        return Err(invalid(value.offset));
    }
    control.checkpoint().map_err(stopped)?;
    let cached =
        resolver.resolve_cached(source, ledger, value, edges, inverse, viewport, control)?;
    builder.append_cached_paint(scene, cached, channel, control)
}
