263	/// Validate typed owner before entering the lower planner and require its entire
264	/// computed pattern mapping at return. This performs no legacy owned conversion.
265	/// The lower adapter owns/admit/releases its plan/cache allocations via ctx.ledger.
266	pub fn plan_production_definition<'src>(
267	    planner: &mut dyn DefinitionPlanner,
268	    ctx: &mut DefinitionContext<'src, '_>,
269	    kind: DefinitionKind,
270	    element: ElementId,
271	    owner: DefinitionOwner,
272	    transform: Affine,
273	    bounds: [f64; 4],
274	    style: &CssPaint<'src>,
275	    control: &mut dyn WorkControl,
276	) -> Result<ProductionDefinitionPlan<'src>> {
277	    owner.validate(ctx)?;
278	    validate_style(ctx.shared.source(), style, control)?;
279	    ctx.shared
280	        .element(element, crate::memory::add(element.0, 1)?, control)?;
281	    if !vexel_geometry::affine_valid(transform)
282	        || !bounds.into_iter().all(f64::is_finite)
283	        || bounds[2] < 0.
284	        || bounds[3] < 0.
285	    {
286	        return Err(invalid(0));
287	    }
288	    let plan = planner
289	        .plan_owned_definition(ctx, kind, element, owner, transform, bounds, style, control)?;
290	    let (definition, mapping) = match &plan {
291	        ProductionDefinitionPlan::Definition(plan) => (plan, None),
292	        ProductionDefinitionPlan::Pattern { plan, mapping } => (plan, Some(*mapping)),
293	    };
294	    let actual = match &definition.descriptor {
295	        DefinitionDescriptor::Clip(_) => DefinitionKind::Clip,
296	        DefinitionDescriptor::Mask(_) => DefinitionKind::Mask,
297	        DefinitionDescriptor::Pattern(descriptor) => {
298	            if descriptor.definition != element {
299	                return Err(invalid(0));
300	            }
301	            let map = mapping.ok_or_else(|| invalid(0))?;
302	            map.pixel_inverse(*descriptor)?;
303	            let DefinitionTarget::Shape(shape) = owner.target else {
304	                return Err(invalid(0));
305	            };
306	            if ctx
307	                .builder
308	                .scene(ctx.scene)?
309	                .shape(shape)
310	                .ok_or_else(|| invalid(0))?
311	                .source
312	                != map.source_map
313	                || map.bounds != bounds
314	            {
315	                return Err(invalid(0));
316	            }
317	            DefinitionKind::Pattern
318	        }
319	        DefinitionDescriptor::Marker(_) => DefinitionKind::Marker,
320	        DefinitionDescriptor::Filter { filter, primitives } => {
321	            let DefinitionTarget::Group(_) = owner.target else {
322	                return Err(invalid(0));
323	            };
324	            crate::validate::filter(*filter, primitives, control)?;
325	            for p in primitives {
326	                control.charge(WorkKind::FilterPixel, 1).map_err(stopped)?;
327	                if p.source_offset > ctx.shared.source().len() {
328	                    return Err(invalid(p.source_offset));
329	                }
330	            }
331	            DefinitionKind::Filter
332	        }
333	    };
334	    if actual != kind || (kind != DefinitionKind::Pattern && mapping.is_some()) {
335	        return Err(invalid(0));
336	    }
337	    if definition.expansions.len() > 65536 {
338	        return Err(crate::types::limit(LimitKind::References));
339	    }
340	    for expansion in &definition.expansions {
341	        control
342	            .charge(WorkKind::ReferenceProbe, 1)
343	            .map_err(stopped)?;
344	        expansion.range.require(ctx.shared.tokens().len(), 0)?;
345	        validate_style(ctx.shared.source(), &expansion.style, control)?;
346	        if !vexel_geometry::affine_valid(expansion.transform)
347	            || !expansion
348	                .viewport
349	                .into_iter()
350	                .all(|v| v.is_finite() && v > 0.)
351	        {
352	            return Err(invalid(0));
353	        }
354	    }
355	    control.checkpoint().map_err(stopped)?;
356	    Ok(plan)
357	}
