359	fn validate_style(
360	    source: &[u8],
361	    style: &CssPaint<'_>,
362	    control: &mut dyn WorkControl,
363	) -> Result<()> {
364	    for property in vexel_svg_css::Property::ALL {
365	        control.charge(WorkKind::PaintVisit, 1).map_err(stopped)?;
366	        if let Some(value) = style.value(property) {
367	            let bytes = value
368	                .span
369	                .slice(source)
370	                .ok_or_else(|| invalid(value.span.offset))?;
371	            if bytes.as_ptr() != value.bytes.as_ptr() || bytes.len() != value.bytes.len() {
372	                return Err(invalid(value.span.offset));
373	            }
374	        }
375	    }
376	    Ok(())
377	}
