 46	impl<T: Copy> LedgerBuffer<T> {
 47	    fn require(&self, ledger: &ChargeLedger) -> Result<()> {
 48	        if self.values.is_none() {
 49	            return Err(invalid(0));
 50	        }
 51	        ledger.require_lease(self.lease)
 52	    }
 53	    pub fn values<'a>(&'a self, ledger: &ChargeLedger) -> Result<&'a [T]> {
 54	        self.require(ledger)?;
 55	        Ok(self.values.as_ref().ok_or_else(|| invalid(0))?)
 56	    }
 57	    pub fn values_mut<'a>(&'a mut self, ledger: &ChargeLedger) -> Result<&'a mut [T]> {
 58	        self.require(ledger)?;
 59	        Ok(self.values.as_mut().ok_or_else(|| invalid(0))?)
 60	    }
 61	    pub fn capacity(&self, ledger: &ChargeLedger) -> Result<usize> {
 62	        self.require(ledger)?;
 63	        Ok(self.values.as_ref().ok_or_else(|| invalid(0))?.capacity())
 64	    }
 65	    /// No allocation. Poll every real iteration; unpublished suffix is removed
 66	    /// on cancellation, preserving the old values and admitted capacity.
 67	    pub fn append(
 68	        &mut self,
 69	        ledger: &ChargeLedger,
 70	        suffix: &[T],
 71	        control: &mut dyn WorkControl,
 72	    ) -> Result<()> {
 73	        self.require(ledger)?;
 74	        control.checkpoint().map_err(stopped)?;
 75	        let values = self.values.as_mut().ok_or_else(|| invalid(0))?;
 76	        let len = values.len();
 77	        let end = len
 78	            .checked_add(suffix.len())
 79	            .ok_or_else(crate::memory::arithmetic)?;
 80	        if end > values.capacity() {
 81	            return Err(invalid(0));
 82	        }
 83	        let result = (|| {
 84	            for value in suffix {
 85	                control.charge(WorkKind::SourceRead, 1).map_err(stopped)?;
 86	                values.push(*value);
 87	            }
 88	            control.checkpoint().map_err(stopped)
 89	        })();
 90	        if result.is_err() {
 91	            values.truncate(len);
 92	        }
 93	        result
 94	    }
 95	    /// Reserve old+new overlap, then controlled copy, then drop old storage before
 96	    /// releasing its charge. Errors leave old data/token/capacity unchanged.
 97	    pub fn replace_capacity(
 98	        &mut self,
 99	        ledger: &mut ChargeLedger,
100	        tag: AllocationTag,
101	        capacity: usize,
102	        control: &mut dyn WorkControl,
103	    ) -> Result<()> {
104	        self.require(ledger)?;
105	        if capacity < self.values(ledger)?.len() {
106	            return Err(invalid(0));
107	        }
108	        let mut replacement = ledger.allocate_buffer(tag, capacity, control)?;
109	        if let Err(error) = replacement.append(ledger, self.values(ledger)?, control) {
110	            replacement.release(ledger)?;
111	            return Err(error);
112	        }
113	        self.release(ledger)?;
114	        *self = replacement;
115	        Ok(())
116	    }
117	    pub fn truncate(&mut self, ledger: &ChargeLedger, len: usize) -> Result<()> {
118	        self.require(ledger)?;
119	        self.values
120	            .as_mut()
121	            .ok_or_else(|| invalid(0))?
122	            .truncate(len);
123	        Ok(())
124	    }
125	    /// Unconditional after cancellation, checked stale/double/foreign access.
126	    pub fn release(&mut self, ledger: &mut ChargeLedger) -> Result<()> {
127	        self.require(ledger)?;
128	        drop(self.values.take());
129	        ledger.release(self.lease)
130	    }
131	}

