 42	macro_rules! room {
 43	    ($self:ident,$index:expr,$field:ident,$extra:expr,$cap:expr,$pending:expr) => {{
 44	        let pending = $pending;
 45	        let current = add($self.stats.live_bytes, pending)?;
 46	        let available = $self
 47	            .limits
 48	            .reserved_bytes
 49	            .checked_sub(current)
 50	            .ok_or_else(|| limit(LimitKind::ReservedBytes))?;
 51	        // Check all counters before the mutating reserve can transfer old values.
 52	        let history_room = usize::MAX - $self.stats.total_allocated_bytes;
 53	        let available = available.min(history_room);
 54	        if $self.stats.allocation_count == usize::MAX {
 55	            return Err(arithmetic());
 56	        }
 57	        let (new, old) = reserve(&mut $self.scenes[$index].$field, $extra, $cap, available)?;
 58	        if new != 0 {
 59	            $self.stats.peak_live_bytes = $self.stats.peak_live_bytes.max(add(current, new)?);
 60	            $self.stats.total_allocated_bytes = add($self.stats.total_allocated_bytes, new)?;
 61	            $self.stats.allocation_count += 1;
 62	            $self.stats.live_bytes = add($self.stats.live_bytes - old, new)?;
 63	        }
 64	    }};
 65	}
